import fs from 'node:fs';
import path from 'node:path';

const D = 'C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\.tmp-weekly';
const UNZ = path.join(D, 'unz');
const OUT = 'C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\研发-前端-田野-本周工作总结(2026.11.09-11.13).xlsx';
const ZIP = path.join(D, 'out.zip');

const data = JSON.parse(fs.readFileSync(path.join(D, 'data.json'), 'utf8'));

// ---- date helpers (local zone Asia/Shanghai) ----
function serial(y, m, d) {
  return Math.round((Date.UTC(y, m - 1, d) - Date.UTC(1899, 11, 30)) / 86400000);
}
function toSerial(s) {
  const [y, m, d] = s.split('/').map(Number);
  return serial(y, m, d);
}
function dayNum(s) {
  const [y, m, d] = s.split('/').map(Number);
  return Date.UTC(y, m - 1, d) / 86400000;
}

// ---- ordering: date asc, then bug id / task id ----
function idKey(id) {
  const m = id.match(/^(\D*)(\d+)$/);
  if (!m) return [9, 999999];
  const kind = m[1] === 'Bug' ? 0 : 1;
  return [kind, Number(m[2])];
}
function cmp(a, b) {
  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
  const ka = idKey(a.id), kb = idKey(b.id);
  if (ka[0] !== kb[0]) return ka[0] - kb[0];
  return ka[1] - kb[1];
}
const summaryRows = [...data.rows].sort(cmp);
const planRows = [...data.plan].sort(cmp);

// ---- shared strings ----
const strings = [];
const sIdx = new Map();
function si(s) {
  if (sIdx.has(s)) return sIdx.get(s);
  const i = strings.length;
  strings.push(s);
  sIdx.set(s, i);
  return i;
}
function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const HEAD = ['序号', '负责人', '项目名称', '分支名称', '禅道ID', '工作内容',
  '开始时间(yyyy/mm/dd)', '结束时间(yyyy/mm/dd)', null, '任务类型', '目前进度', '备注'];
const OWNER = '田野';

function buildRows(rows, hoursHeader) {
  const head = HEAD.slice();
  head[8] = hoursHeader;
  const grid = [];
  grid.push(head.map((h, i) => ({ v: h, t: 's', s: 5 })));
  rows.forEach((r, i) => {
    grid.push([
      { v: String(i + 1), t: 'n', s: 6 },
      { v: OWNER, t: 's', s: 6 },
      { v: r.proj, t: 's', s: 6 },
      { v: r.branch, t: 's', s: 6 },
      { v: r.id, t: 's', s: 6 },
      { v: r.content, t: 's', s: 7 },
      { v: String(toSerial(r.start)), t: 'n', s: 8 },
      { v: String(toSerial(r.end)), t: 'n', s: 8 },
      { v: String(r.hours), t: 'n', s: 6 },
      { v: r.type, t: 's', s: 6 },
      { v: r.progress || '', t: 's', s: 6 },
      { v: r.note || '', t: 's', s: 7 },
    ]);
  });
  return grid;
}

const COLS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L'];

function sheetXml(grid, title, hoursHeader) {
  const lastRow = grid.length + 1; // title occupies row 1
  const cell = (ci, val, r) => {
    const ref = COLS[ci] + r;
    if (val.t === 'n') return `<c r="${ref}" s="${val.s}"><v>${val.v}</v></c>`;
    if (val.v === '' || val.v == null) return `<c r="${ref}" s="${val.s}" t="s"/>`;
    return `<c r="${ref}" s="${val.s}" t="s"><v>${si(val.v)}</v></c>`;
  };

  let xml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';
  xml += `<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetPr/><dimension ref="L${lastRow + 2}"/><sheetViews><sheetView showGridLines="1"${title.startsWith('研发部2026.11.09') ? ' tabSelected="1"' : ''} workbookViewId="0"/></sheetViews><sheetFormatPr defaultColWidth="9.23077" defaultRowHeight="16.8"/>`;
  xml += '<cols><col min="1" max="1" width="9.23077" style="18" customWidth="1"/><col min="2" max="2" width="14.0962" style="18" customWidth="1"/><col min="3" max="3" width="21.4712" style="18" customWidth="1"/><col min="4" max="4" width="25.4808" style="18" customWidth="1"/><col min="5" max="5" width="16.0" style="27" customWidth="1"/><col min="6" max="6" width="60" customWidth="1"/><col min="7" max="7" width="22.4808" style="18" customWidth="1"/><col min="8" max="8" width="22.3846" style="18" customWidth="1"/><col min="9" max="9" width="15.7788" style="18" customWidth="1"/><col min="10" max="10" width="13.6635" style="18" customWidth="1"/><col min="11" max="11" width="11.9423" style="18" customWidth="1"/><col min="12" max="12" width="34.0577" style="18" customWidth="1"/></cols><sheetData>';

  // title row
  xml += `<row r="1" spans="1:12" ht="29" customHeight="1">`;
  for (let i = 0; i < 12; i++) {
    if (i === 0) xml += `<c r="A1" s="4" t="s"><v>${si(title)}</v></c>`;
    else xml += `<c r="${COLS[i]}1" s="4" t="s"/>`;
  }
  xml += '</row>';

  grid.forEach((rowVals, ri) => {
    const r = ri + 2;
    const isHead = ri === 0;
    xml += `<row r="${r}" spans="1:12"${isHead ? ' ht="25" customHeight="1"' : ''}>`;
    rowVals.forEach((val, ci) => { xml += cell(ci, val, r); });
    xml += '</row>';
  });

  xml += '</sheetData><mergeCells count="1"><mergeCell ref="A1:L1"/></mergeCells>';
  xml += `<dataValidations><dataValidation type="list" operator="between" allowBlank="1" showInputMessage="1" showErrorMessage="1" sqref="J2:J${grid.length + 1}"><formula1>"BUG修复,功能开发,版本迁移,其他"</formula1></dataValidation></dataValidations>`;
  xml += '<pageMargins left="0.75" right="0.75" top="1" bottom="1" header="0.5" footer="0.5"/><headerFooter/></worksheet>';
  return xml;
}

// build grids BEFORE writing sharedStrings (si() populates)
const grid1 = buildRows(summaryRows, HEAD[8]);
const grid2 = buildRows(planRows, '预估时长(h)');
const xml1 = sheetXml(grid1, data.week.summary, '完成时长(h)');
const xml2 = sheetXml(grid2, data.week.plan, '预估时长(h)');

// sharedStrings.xml
let ss = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';
ss += `<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="${strings.length}" uniqueCount="${strings.length}">`;
for (const s of strings) ss += `<si><t xml:space="preserve">${esc(s)}</t></si>`;
ss += '</sst>';

fs.mkdirSync(path.join(D, 'new'), { recursive: true });
const NEW = path.join(D, 'new');
function copy(rel) {
  const src = path.join(UNZ, rel);
  const dst = path.join(NEW, rel);
  fs.mkdirSync(path.dirname(dst), { recursive: true });
  fs.copyFileSync(src, dst);
}
['[Content_Types].xml', 'docProps/app.xml', 'docProps/core.xml', 'docProps/custom.xml',
  '_rels/.rels', 'xl/_rels/workbook.xml.rels', 'xl/workbook.xml', 'xl/styles.xml',
  'xl/theme/theme1.xml'].forEach(copy);
fs.writeFileSync(path.join(NEW, 'xl/sharedStrings.xml'), ss, 'utf8');
fs.writeFileSync(path.join(NEW, 'xl/worksheets/sheet1.xml'), xml1, 'utf8');
fs.writeFileSync(path.join(NEW, 'xl/worksheets/sheet2.xml'), xml2, 'utf8');

// zip via pwsh Compress-Archive is done outside; print summary
const sumH = summaryRows.reduce((a, b) => a + Number(b.hours), 0);
const planH = planRows.reduce((a, b) => a + Number(b.hours), 0);
console.log(JSON.stringify({ summaryRows: summaryRows.length, sumH, planRows: planRows.length, planH, ssCount: strings.length }, null, 2));

